#include <map>
#include <algorithm>

int main() {
    std::map<int, std::string> m = {{1, "A"}, {2, "B"}, {3, "C"}};

    // INCORRECT: std::remove modifies elements via overwrite
    // auto new_end = std::remove(m.begin(), m.end(), std::make_pair(2, "B")); 
    // ^ Will fail compilation or cause UB due to const key

    // CORRECT: Use the member function erase
    auto it = m.find(2);
    if (it != m.end()) {
        m.erase(it); // O(log N) operation
    }
}
